local rescue = false
function event_signal(e)
  if e.signal ~= 7 or rescue then return end
  rescue = true
  -- Combat pursuit already runs. SetRunning controls the unused source patrol;
  -- mixing that patrol command with hate would fail shared runtime preflight.
  eq.attack_npc_type(2000944)
  eq.set_timer("leave", 1200000)
end
function event_timer(e)
  if e.timer == "leave" and rescue then eq.stop_timer("leave"); eq.depop() end
end
function event_death_complete(e)
  eq.stop_timer("leave")
end
